/**
 * WHY A SPOOL ROW IS NOT COUNTED, by its code (wave 13r round AG). Each row of GATES_THE_SPOOL_WAITS_FOR
 * (src/config/gate-count-spool.mjs) names one, and the Gates page says it under that row. Each reason is also the last
 * sentence of its rows' words.
 */
export const WHY_A_SPOOL_ROW_WAITS = Object.freeze({
  'from-inside': "This check also runs on a start from inside the sandbox, under an agent's own command, whose output the host never reads. A line printed from inside is only the sandbox's own word, so this row is not counted.",
  'at-the-runs-end': "This check runs at the run's end, after the host has stopped reading the run's output, so this row is not counted.",
})
/**
 * The four gates that hold a message in the queue, in the order the message worker asks them.
 * @typedef {typeof MESSAGE_HOLDS[number]} MessageHold
 */
export const MESSAGE_HOLDS = Object.freeze(/** @type {const} */ (['held-by-a-notice-rule', 'held-while-a-resident-sleeps', 'held-by-an-unsent-review', 'wait-for-the-persons-start']))
/** @param {string} id @returns {Gate} */
export function gateNamed(id) {
  const row = GATES.find(row => row.id === id)
  if (row === undefined) throw new Error(`No gate is named "${id}".`)
  return row
}
/** @param {string} setting */
export function gateForSetting(setting) { return GATES.find(row => row.setting === setting) }
/** @param {Pick<Gate, 'positions'>} row @param {string} value */
export function gateValueIsAllowed(row, value) {
  if (row.positions.kind === 'switch') return value === '0' || value === '1'
  if (row.positions.kind === 'block-remind-off') return row.positions.allowed.some(one => one === value)
  return /^\d+$/.test(value) && Number.isSafeInteger(Number(value)) && Number(value) >= row.positions.fewest && Number(value) <= row.positions.most
}
